# =========================================================
# COINr Builder — R replication script generator
# Mirrors the exact COINr calls the app makes, so the script
# reproduces the session top-to-bottom with only COINr.
# =========================================================

build_script <- function(s) {
  L <- character(0)
  add <- function(...) L <<- c(L, ...)

  add("# =========================================================",
      paste0("# ", s$session_name),
      "# COINr replication script - generated by COINr Builder",
      paste0("# ", format(Sys.Date(), "%Y-%m-%d")),
      "# =========================================================",
      "library(COINr)",
      "")

  # 1 | data
  if (s$is_example) {
    add("# 1 | Assemble the coin from the bundled ASEM example data",
        "iData <- ASEM_iData",
        "iMeta <- ASEM_iMeta")
  } else {
    add("# 1 | Assemble the coin from your data files",
        sprintf('iData <- read.csv("%s")', s$idata_file),
        sprintf('iMeta <- read.csv("%s")', s$imeta_file))
  }

  # denominator assignments changed in the app are written back into iMeta
  if (length(s$den_changes)) {
    add("# Denominator assignments edited in the app:")
    for (code in names(s$den_changes)) {
      v <- s$den_changes[[code]]
      if (is.na(v)) {
        add(sprintf('iMeta$Denominator[iMeta$iCode == "%s"] <- NA', code))
      } else {
        add(sprintf('iMeta$Denominator[iMeta$iCode == "%s"] <- "%s"', code, v))
      }
    }
  }
  add("coin <- new_coin(iData, iMeta,",
      sprintf("  level_names = c(%s))", paste0('"', s$lev_names, '"', collapse = ", ")),
      "")

  dset <- "Raw"

  # 2 | denomination
  if (s$any_denom) {
    add("# 2 | Denominate size-dependent indicators (specs in iMeta)",
        sprintf('coin <- Denominate(coin, dset = "%s")', dset))
    dset <- "Denominated"
  } else {
    add("# 2 | Denomination skipped - no denominators assigned")
  }
  add("")

  # 3 | screening
  add(sprintf("# 3 | Screen units below %d%% data availability", round(s$thresh * 100)))
  if (length(s$force_kept)) {
    add(sprintf('coin <- Screen(coin, dset = "%s", unit_screen = "byNA",', dset),
        sprintf("  dat_thresh = %s,", s$thresh),
        sprintf("  Force = data.frame(uCode = c(%s),", paste0('"', s$force_kept, '"', collapse = ", ")),
        "                     Include = TRUE))")
  } else {
    add(sprintf('coin <- Screen(coin, dset = "%s", unit_screen = "byNA",', dset),
        sprintf("  dat_thresh = %s)", s$thresh))
  }
  dset <- "Screened"
  add("")

  # 4 | imputation
  if (s$impute_method == "none") {
    add("# 4 | Imputation skipped - missing values remain")
  } else if (s$impute_method == "i_mean_grp") {
    add("# 4 | Impute missing values: group mean",
        sprintf('coin <- Impute(coin, dset = "%s", f_i = "i_mean_grp",', dset),
        sprintf('  use_group = "%s")', s$impute_group))
    dset <- "Imputed"
  } else {
    add("# 4 | Impute missing values",
        sprintf('coin <- Impute(coin, dset = "%s", f_i = "%s")', dset, s$impute_method))
    dset <- "Imputed"
  }
  add("")

  # 5 | treatment
  add(sprintf("# 5 | Treat outliers: winsorise up to %s points, log if insufficient", s$winmax),
      sprintf('coin <- Treat(coin, dset = "%s", global_specs = list(', dset),
      '  f1 = "winsorise",',
      sprintf("  f1_para = list(winmax = %s, skew_thresh = %s,", s$winmax, s$skew),
      sprintf("                 kurt_thresh = %s),", s$kurt),
      '  f2 = "log_CT"))')
  dset <- "Treated"
  add("")

  # 6 | normalisation
  nm <- method_by_id(NORM_METHODS, s$norm_method)
  add(paste0("# 6 | Normalise: ", tolower(nm$title)))
  if (s$norm_method == "n_minmax") {
    add(sprintf('coin <- Normalise(coin, dset = "%s", global_specs = list(', dset),
        sprintf('  f_n = "n_minmax", f_n_para = list(l_u = c(%s, %s))))', s$norm_min, s$norm_max))
  } else if (s$norm_method == "n_zscore") {
    add(sprintf('coin <- Normalise(coin, dset = "%s", global_specs = list(', dset),
        '  f_n = "n_zscore", f_n_para = list(m_sd = c(0, 1))))')
  } else {
    add(sprintf('coin <- Normalise(coin, dset = "%s",', dset),
        sprintf('  global_specs = list(f_n = "%s"))', s$norm_method))
  }
  add("")

  # 7 | weights
  add("# 7 | Weights (relative within each aggregation group)",
      "w <- coin$Meta$Weights$Original")
  if (length(s$w_changes)) {
    for (code in names(s$w_changes)) {
      add(sprintf('w$Weight[w$iCode == "%s"] <- %s', code, fmt2(s$w_changes[[code]])))
    }
  } else {
    add("# (original equal weights from iMeta)")
  }
  add("")

  # 8 | aggregation
  am <- method_by_id(AGG_METHODS, s$agg_method)
  add(paste0("# 8 | Aggregate: ", tolower(am$title)),
      sprintf('coin <- Aggregate(coin, dset = "Normalised", f_ag = "%s", w = w)', s$agg_method),
      "")

  # 9 | results
  add("# 9 | Results: scores and ranks at every level",
      'df_results <- get_results(coin, dset = "Aggregated", tab_type = "Aggs",',
      '  also_get = "uName", nround = 1)',
      "head(df_results, 10)")

  # 10 | sensitivity
  n_next <- 10
  if (!is.null(s$sens)) {
    add("",
        sprintf("# 10 | Uncertainty analysis: %s replications", s$sens$N),
        "SA_specs <- list(")
    specs <- character(0)
    if (s$sens$w) {
      specs <- c(specs, paste(
        '  Weights = list(Address = "$Log$Aggregate$w",',
        "    Distribution = get_noisy_weights(w = w,",
        "      noise_specs = data.frame(Level = 2, NoiseFactor = 0.25),",
        sprintf("      Nrep = %s),", s$sens$N),
        '    Type = "discrete", Name = "Weights")', sep = "\n"))
    }
    if (s$sens$norm) {
      specs <- c(specs, paste(
        '  Normalisation = list(Address = "$Log$Normalise$global_specs",',
        "    Distribution = list(",
        sprintf("      list(f_n = \"n_minmax\", f_n_para = list(l_u = c(%s, %s))),", s$norm_min, s$norm_max),
        '      list(f_n = "n_zscore", f_n_para = list(m_sd = c(50, 10)))),',
        '    Type = "discrete", Name = "Normalisation")', sep = "\n"))
    }
    if (s$sens$agg) {
      specs <- c(specs, paste(
        '  Aggregation = list(Address = "$Log$Aggregate$f_ag",',
        '    Distribution = c("a_amean", "a_gmean"),',
        '    Type = "discrete", Name = "Aggregation")', sep = "\n"))
    }
    add(strsplit(paste(specs, collapse = ",\n"), "\n")[[1]])
    add(")",
        sprintf("SA <- get_sensitivity(coin, SA_specs = SA_specs, N = %s,", s$sens$N),
        '  SA_type = "UA", dset = "Aggregated", iCode = "Index")',
        "plot_uncertainty(SA)")
    n_next <- 11
  }

  # export
  add("",
      sprintf("# %d | Export the full coin to Excel", n_next),
      sprintf('export_to_excel(coin, fname = "%s")', s$xlsx_name))
  L
}
